What is the output of the following Python code?

def decorator(func):
    call_count = 0
    def wrapper(*args):
        nonlocal call_count
        call_count += 1
        return func(*args)
    return wrapper

@decorator
def add(a, b):
    return a + b

print(add(2,3), add(4,5))

What is the output of the following recursive function?

def f(n):
    if n <= 0:
        return 1
    return n * f(n-2)

print(f(7))
